// ─── File: src/test/java/com/bank/compare/RaceVsDeadlockTest.java ───
package com.bank.compare;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class RaceVsDeadlockTest {

    // ═══ RACE CONDITION: program runs, wrong result ═══
    @Test
    void raceCondition_wrongResult_programContinues() throws InterruptedException {
        int[] balance = {100};
        int threads = 100;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int i = 0; i < threads; i++) {
            new Thread(() -> {
                balance[0] -= 1;  // race! read-modify-write not atomic
                latch.countDown();
            }).start();
        }
        latch.await();

        // Program finished! But result might be wrong.
        System.out.println("Race result: " + balance[0] + " (expected 0)");
        // balance[0] might be > 0 → lost decrements (silent corruption!)
    }

    // ═══ DEADLOCK: program freezes, no result ═══
    @Test
    void deadlock_demonstration_withTimeout() throws InterruptedException {
        Object lockA = new Object();
        Object lockB = new Object();
        AtomicBoolean t1Done = new AtomicBoolean(false);
        AtomicBoolean t2Done = new AtomicBoolean(false);

        Thread t1 = new Thread(() -> {
            synchronized (lockA) {
                try { Thread.sleep(50); } catch (InterruptedException e) { return; }
                synchronized (lockB) { t1Done.set(true); }
            }
        });

        Thread t2 = new Thread(() -> {
            synchronized (lockB) {
                try { Thread.sleep(50); } catch (InterruptedException e) { return; }
                synchronized (lockA) { t2Done.set(true); }
            }
        });

        t1.start(); t2.start();
        // Wait only 2 seconds — if deadlocked, threads won't finish
        t1.join(2000); t2.join(2000);

        // If deadlocked: both threads still alive, neither completed
        if (!t1Done.get() && !t2Done.get() && t1.isAlive() && t2.isAlive()) {
            System.out.println("DEADLOCK detected! Threads frozen.");
            t1.interrupt(); t2.interrupt();  // cleanup
        }
        t1.join(); t2.join();
    }

    // ═══ FIX RACE: AtomicInteger ═══
    @Test
    void fixRace_atomic() throws InterruptedException {
        AtomicInteger balance = new AtomicInteger(100);
        int threads = 100;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int i = 0; i < threads; i++) {
            new Thread(() -> { balance.decrementAndGet(); latch.countDown(); }).start();
        }
        latch.await();
        assertThat(balance.get()).isEqualTo(0);  // ALWAYS correct!
    }

    // ═══ FIX DEADLOCK: lock ordering ═══
    @Test
    void fixDeadlock_lockOrdering() throws InterruptedException {
        Object lockA = new Object();
        Object lockB = new Object();
        // BOTH threads lock in A→B order
        AtomicInteger completed = new AtomicInteger(0);
        CountDownLatch latch = new CountDownLatch(2);

        for (int i = 0; i < 2; i++) {
            new Thread(() -> {
                synchronized (lockA) {
                    synchronized (lockB) {
                        completed.incrementAndGet();
                    }
                }
                latch.countDown();
            }).start();
        }
        boolean done = latch.await(5, TimeUnit.SECONDS);
        assertThat(done).isTrue();
        assertThat(completed.get()).isEqualTo(2);  // both completed! No deadlock!
    }
}
